// Writes src/shared/i18n-keys.ts from content/i18n/ru.json (ADR-0160, TSK-0676): a union of the
// keys and a parameter type for each key's placeholders, so a missing key or parameter fails the
// type check. A value is a string with {name} placeholders, a plural object with `one`, `few`,
// `many` and `other`, or a System message, an array of lines in which {"pause": "..."} is the
// self-correction. The generated file is committed, and the lint run fails when it is stale.
//   tsx tools/gen-keys.ts          writes the file
import { readFileSync, writeFileSync } from "node:fs";
import { format } from "prettier";

export type Line = string | { pause: string };
export type Plural = Record<"one" | "few" | "many" | "other", string>;
export type Value = string | Plural | Line[];

export const FORMS = ["one", "few", "many", "other"] as const;

const PLACEHOLDER = /\{(\w+)\}/g;

/** The placeholder names of every string a value holds. */
export function placeholdersOf(value: Value): string[] {
  const texts = Array.isArray(value)
    ? value.map((l) => (typeof l === "string" ? l : l.pause))
    : typeof value === "string"
      ? [value]
      : Object.values(value);
  const names = new Set<string>();
  for (const text of texts)
    for (const m of text.matchAll(PLACEHOLDER)) names.add(m[1] as string);
  return [...names].sort();
}

export const isPlural = (v: Value): v is Plural =>
  typeof v === "object" && !Array.isArray(v);

/** The text of src/shared/i18n-keys.ts for a language file. */
export async function renderKeys(file: Record<string, Value>): Promise<string> {
  const keys = Object.keys(file);
  const params = keys.map((key) => {
    const value = file[key] as Value;
    const names = placeholdersOf(value);
    const fields = [
      ...(isPlural(value) ? ["n: number"] : []),
      ...names.map((n) => `${n}: string | number`),
    ];
    return `${JSON.stringify(key)}: ${fields.length ? `{ ${fields.join("; ")} }` : "NoParams"};`;
  });
  const keyList = (pick: (v: Value) => boolean): string => {
    const picked = keys.filter((k) => pick(file[k] as Value));
    return picked.length
      ? picked.map((k) => JSON.stringify(k)).join(" | ")
      : "never";
  };
  const source = `// Generated by tools/gen-keys.ts from content/i18n/ru.json. Do not edit.
export type NoParams = Record<never, never>;

export interface StringParams {
${params.join("\n")}
}

export type Key = keyof StringParams;
/** Keys whose value is a plural object: the call passes \`n\`. */
export type PluralKey = ${keyList(isPlural)};
/** Keys whose value is a System message, an array of lines. */
export type LinesKey = ${keyList(Array.isArray)};
`;
  return format(source, { parser: "typescript" });
}

const RU = new URL("../content/i18n/ru.json", import.meta.url);
const OUT = new URL("../src/shared/i18n-keys.ts", import.meta.url);

export const readLanguage = (): Record<string, Value> =>
  JSON.parse(readFileSync(RU, "utf8")) as Record<string, Value>;

export const generatedKeys = (): string => readFileSync(OUT, "utf8");

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(OUT, await renderKeys(readLanguage()));
  console.log("gen-keys: wrote src/shared/i18n-keys.ts");
}
